// Normalize Instagram DMs
const igData = $('Fetch Instagram DMs').first().json;
const igMessages = [];

if (igData && igData.data) {
  for (const convo of igData.data) {
    const participants = convo.participants ? convo.participants.data : [];
    const participantNames = participants.map(p => p.name || p.username || p.id).join(', ');

    if (convo.messages && convo.messages.data) {
      for (const msg of convo.messages.data) {
        // Skip messages sent by our own page/account
        const fromName = msg.from ? (msg.from.name || msg.from.username || msg.from.id) : 'unknown';

        igMessages.push({
          platform: 'instagram',
          conversation_id: convo.id,
          message_id: msg.id,
          from_name: fromName,
          from_id: msg.from ? msg.from.id : '',
          message_text: msg.message || '',
          timestamp: msg.created_time || new Date().toISOString(),
          participants: participantNames,
          fetched_at: new Date().toISOString()
        });
      }
    }
  }
}

// Normalize Facebook Messenger DMs
const fbData = $('Fetch Facebook Messenger DMs').first().json;
const fbMessages = [];

if (fbData && fbData.data) {
  for (const convo of fbData.data) {
    const participants = convo.participants ? convo.participants.data : [];
    const participantNames = participants.map(p => p.name || p.id).join(', ');

    if (convo.messages && convo.messages.data) {
      for (const msg of convo.messages.data) {
        const fromName = msg.from ? (msg.from.name || msg.from.id) : 'unknown';

        fbMessages.push({
          platform: 'facebook_messenger',
          conversation_id: convo.id,
          message_id: msg.id,
          from_name: fromName,
          from_id: msg.from ? msg.from.id : '',
          message_text: msg.message || '',
          timestamp: msg.created_time || new Date().toISOString(),
          participants: participantNames,
          fetched_at: new Date().toISOString()
        });
      }
    }
  }
}

const allMessages = [...igMessages, ...fbMessages];

if (allMessages.length === 0) {
  return [{ json: { _noMessages: true, message: 'No DMs found in this cycle' } }];
}

return allMessages.map(m => ({ json: m }));

// Get list of already-processed message IDs from Google Sheets
const sheetsData = $('Fetch Processed DM IDs').first().json;
const processedIds = new Set();

if (sheetsData && sheetsData.values) {
  for (const row of sheetsData.values) {
    if (row[0]) processedIds.add(row[0]);
  }
}

// Filter out already-processed messages and messages from our own page
const allItems = $input.all();
const newMessages = [];
const pageId = $env.META_PAGE_ID || '';
const igUserId = $env.META_IG_USER_ID || '';

for (const item of allItems) {
  if (item.json._noMessages) continue;

  // Skip if already processed
  if (processedIds.has(item.json.message_id)) continue;

  // Skip messages sent by our own page/account
  if (item.json.from_id === pageId || item.json.from_id === igUserId) continue;

  // Skip empty messages
  if (!item.json.message_text || item.json.message_text.trim() === '') continue;

  // Only process messages from the last 30 minutes to avoid old message backlog
  const msgTime = new Date(item.json.timestamp).getTime();
  const thirtyMinsAgo = Date.now() - (30 * 60 * 1000);
  if (msgTime < thirtyMinsAgo) continue;

  newMessages.push(item);
}

if (newMessages.length === 0) {
  return [{ json: { _noNewMessages: true, message: 'No new DMs to process' } }];
}

return newMessages;

