// Parse the LLM response and merge with original DM data
const llmResponse = $json;
const originalDM = $('Has New DMs?').item;

let classification = {};

try {
  const content = llmResponse.choices[0].message.content;

  // Remove markdown code block wrapping if present
  let jsonStr = content;
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1].trim();
  }

  classification = JSON.parse(jsonStr);
} catch (e) {
  // Fallback classification
  classification = {
    category: 'GENERAL',
    priority: 3,
    suggested_reply_hindi: 'नमस्ते! 🙏 Divine Hindu में आपका स्वागत है। हम जल्द ही आपसे संपर्क करेंगे।',
    suggested_reply_english: 'Namaste! 🙏 Welcome to Divine Hindu. We will get back to you shortly.',
    route_to: 'auto',
    urgency: 'medium',
    reasoning: 'LLM parse error - defaulting to safe classification: ' + (e.message || 'unknown')
  };
}

// Validate fields
const validCategories = ['HOT_LEAD', 'SUPPORT_REQUEST', 'PRICE_INQUIRY', 'ORDER_STATUS', 'COLLABORATION', 'SPAM', 'GENERAL'];
const validRoutes = ['sales', 'support', 'marketing', 'auto'];
const validUrgencies = ['low', 'medium', 'high', 'critical'];

if (!validCategories.includes(classification.category)) classification.category = 'GENERAL';
if (!validRoutes.includes(classification.route_to)) classification.route_to = 'auto';
if (!validUrgencies.includes(classification.urgency)) classification.urgency = 'medium';
if (typeof classification.priority !== 'number' || classification.priority < 1 || classification.priority > 5) classification.priority = 3;

return [{
  json: {
    ...originalDM.json,
    category: classification.category,
    priority: classification.priority,
    suggested_reply_hindi: classification.suggested_reply_hindi || '',
    suggested_reply_english: classification.suggested_reply_english || '',
    route_to: classification.route_to,
    urgency: classification.urgency,
    reasoning: classification.reasoning || '',
    classified_at: new Date().toISOString()
  }
}];

