// WhatsApp Business API Alert
// Requires: META_WHATSAPP_PHONE_NUMBER_ID and META_ACCESS_TOKEN with whatsapp_business_messaging permission
// If WHATSAPP_NUMBER_ID env var is not set, this step is skipped gracefully

const item = $input.item.json;
const phoneNumberId = $env.META_WHATSAPP_PHONE_NUMBER_ID || '';
const toNumber = $env.WHATSAPP_ALERT_TO_NUMBER || '';
const token = $env.META_ACCESS_TOKEN;

if (!phoneNumberId || !toNumber) {
  return [{ json: { ...item, whatsapp_result: 'skipped', whatsapp_note: 'META_WHATSAPP_PHONE_NUMBER_ID or WHATSAPP_ALERT_TO_NUMBER not configured' } }];
}

const body = {
  messaging_product: 'whatsapp',
  to: toNumber,
  type: 'text',
  text: {
    body: '🔥 HOT LEAD on ' + item.platform + '\nFrom: ' + item.from_name + '\nMessage: ' + item.message_text + '\n\nPriority: ' + item.priority + '/5\nRespond within 15 minutes!'
  }
};

try {
  const resp = await fetch(`https://graph.facebook.com/v19.0/${phoneNumberId}/messages`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
    body: JSON.stringify(body)
  });
  const result = await resp.json();
  return [{ json: { ...item, whatsapp_result: result } }];
} catch(e) {
  return [{ json: { ...item, whatsapp_result: 'error: ' + e.message } }];
}

// Auto-acknowledge DM — handles Instagram vs Facebook Messenger correctly
const item = $input.item.json;
const token = $env.META_ACCESS_TOKEN;
const platform = item.platform;
const fromId = item.from_id;
const convoId = item.conversation_id;

const replyText = platform === 'instagram'
  ? `नमस्ते! 🙏 आपकी inquiry मिल गई। हमारी Sales team 15 मिनट में आपसे संपर्क करेगी। Divine Hindu में आपका स्वागत है!`
  : `Namaste! 🙏 We have received your inquiry. Our Sales team will contact you within 15 minutes.`;

let url, bodyData;

if (platform === 'instagram') {
  // Instagram Messaging API format
  url = `https://graph.facebook.com/v19.0/me/messages?access_token=${token}`;
  bodyData = {
    recipient: { id: fromId },
    message: { text: replyText },
    messaging_type: 'RESPONSE'
  };
} else {
  // Facebook Messenger API format
  url = `https://graph.facebook.com/v19.0/${convoId}/messages?access_token=${token}`;
  bodyData = { message: replyText };
}

try {
  const resp = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(bodyData)
  });
  const result = await resp.json();
  return [{ json: { ...item, ack_result: result, ack_sent: true } }];
} catch(e) {
  return [{ json: { ...item, ack_result: e.message, ack_sent: false } }];
}

