// Prepare row data for DM Tracker Google Sheets logging
const item = $input.first().json;
const now = new Date().toISOString();

const responseTimeMs = item.classified_at && item.fetched_at 
  ? (new Date(now).getTime() - new Date(item.fetched_at).getTime()) 
  : 0;

const row = {
  timestamp: item.timestamp || now,
  platform: item.platform || 'unknown',
  message_id: item.message_id || '',
  conversation_id: item.conversation_id || '',
  from_name: item.from_name || '',
  message_text: item.message_text || '',
  category: item.category || '',
  route_to: item.route_to || '',
  priority: item.priority || 3,
  urgency: item.urgency || 'medium',
  suggested_reply_hindi: item.suggested_reply_hindi || '',
  suggested_reply_english: item.suggested_reply_english || '',
  action_taken: 'YES',
  response_time_ms: responseTimeMs,
  logged_at: now
};

return [{ json: row }];
